import { createMemo, createResource, Show, Suspense, type Component, type ParentComponent } from "solid-js";

import { Flipbook } from "#core/ui-next/components/flipbook.jsx"
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { createSignalFromExistingDebugWidget } from "#core/ui-next/utilities/debug-widgets.js";

export interface ThrobberComponentProps {
	/** An optional caption shown under the animation. */
	caption?: string;

	class?: string;
}

UI.Debug.registerWidget({
	caption: "Force 3s delay on <ThrobberSuspense> components.",
	category: "Debug",
	domainType: "bool",
	id: "forceDelayOnThrobberSuspense",
	value: false,
});

const ThrobberComponent: Component<ThrobberComponentProps> = (props) => {
	return (
		<div class={`flex justify-center items-center ${props.class ?? ""}`}>
			<div class="flex flex-col justify-center items-center">
				<Flipbook.Hourglass class="size-22" />
				<Show when={props.caption != null}>
					<L10n.Stylize text={props.caption!} />
				</Show>

			</div>
		</div>
	);
};

/**
 * A Throbber component, implemented using our standard hourglass animation.
*/
export const Throbber = ComponentRegistry.register({
	name: "Throbber",
	createInstance: ThrobberComponent,
	images: [

	],
});

const ThrobberSuspenseComponent: ParentComponent<ThrobberComponentProps> = (props) => {

	const forceSuspenseDelay = createSignalFromExistingDebugWidget("forceDelayOnThrobberSuspense");

	const debugDelayResource = createMemo(() => {
		const value = forceSuspenseDelay();
		if (value !== null && value == true) {
			const [resource] = createResource(async () => {
				const p = new Promise<void>((resolve, _reject) => {
					setTimeout(resolve, 3000);
				})

				await p;
			});
			return resource;
		}

		return null;
	});


	return (
		<Suspense fallback={<Throbber caption={props.caption} class={props.class} />}>
			{(() => {
				const resource = debugDelayResource();
				if (resource) {
					resource();
				}
				return props.children;
			})()}
		</Suspense>
	);
}

/**
 * A Suspense component that uses a Throbber as a fallback.
*/
export const ThrobberSuspense = ComponentRegistry.register({
	name: "ThrobberSuspense",
	createInstance: ThrobberSuspenseComponent,
});